--
-- Table structure for table `thoi_khoa_bieu`
--

DROP TABLE IF EXISTS `thoi_khoa_bieu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `thoi_khoa_bieu` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ma_mon` varchar(20) NOT NULL,
  `ma_lop` varchar(20) NOT NULL,
  `ma_gv` varchar(20) NOT NULL,
  `ma_phong` varchar(20) NOT NULL,
  `thu_trong_tuan` int(11) NOT NULL COMMENT '2: Thứ Hai, ..., 8: Chủ Nhật',
  `tiet_bat_dau` int(11) NOT NULL COMMENT '1 đến 12',
  `so_tiet` int(11) NOT NULL COMMENT 'Số tiết (1 đến 6)',
  `tiet_ket_thuc` int(11) NOT NULL COMMENT 'tiet_bat_dau + so_tiet - 1',
  `tuan_bat_dau` int(11) NOT NULL COMMENT 'Tuần bắt đầu (VD: 1)',
  `tuan_ket_thuc` int(11) NOT NULL COMMENT 'Tuần kết thúc (VD: 15)',
  `hoc_ky` varchar(20) NOT NULL COMMENT 'HK1, HK2, HK3 (Hè)',
  `nam_hoc` varchar(20) NOT NULL COMMENT 'VD: 2025-2026',
  `ghi_chu` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_tkb_mon` (`ma_mon`),
  KEY `idx_tkb_phong` (`ma_phong`),
  KEY `idx_tkb_gv` (`ma_gv`),
  KEY `idx_tkb_lop` (`ma_lop`),
  KEY `idx_tkb_thoigian` (`hoc_ky`,`nam_hoc`,`thu_trong_tuan`,`tiet_bat_dau`,`tiet_ket_thuc`),
  CONSTRAINT `fk_tkb_gv` FOREIGN KEY (`ma_gv`) REFERENCES `giang_vien` (`ma_gv`) ON UPDATE CASCADE,
  CONSTRAINT `fk_tkb_lop` FOREIGN KEY (`ma_lop`) REFERENCES `lop_hoc` (`ma_lop`) ON UPDATE CASCADE,
  CONSTRAINT `fk_tkb_mon` FOREIGN KEY (`ma_mon`) REFERENCES `mon_hoc` (`ma_mon`) ON UPDATE CASCADE,
  CONSTRAINT `fk_tkb_phong` FOREIGN KEY (`ma_phong`) REFERENCES `phong_hoc` (`ma_phong`) ON UPDATE CASCADE,
  CONSTRAINT `chk_thu_tuan` CHECK (`thu_trong_tuan` between 2 and 8),
  CONSTRAINT `chk_tiet_bat_dau` CHECK (`tiet_bat_dau` between 1 and 12),
  CONSTRAINT `chk_so_tiet` CHECK (`so_tiet` between 1 and 6),
  CONSTRAINT `chk_tiet_ket_thuc` CHECK (`tiet_ket_thuc` between 1 and 12 and `tiet_ket_thuc` >= `tiet_bat_dau`),
  CONSTRAINT `chk_tuan` CHECK (`tuan_bat_dau` >= 1 and `tuan_ket_thuc` >= `tuan_bat_dau`)
) ENGINE=InnoDB AUTO_INCREMENT=691 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

